def _link_existing_entries():
    """One player per sport per distinct name (case and spacing ignored); the TD merges other spellings later."""
    from datetime import datetime, timezone

    conn = op.get_bind()
    tournaments = sa.table('tournaments', sa.column('id'), sa.column('sport'), sa.column('created_at'))
    participants = sa.table('participants', sa.column('id'), sa.column('tournament_id'), sa.column('name'),
                            sa.column('club'), sa.column('player_id'))
    players = sa.table('players', sa.column('id'), sa.column('sport'), sa.column('name'), sa.column('club'),
                       sa.column('created_at'))
    rows = conn.execute(
        sa.select(participants.c.id, participants.c.name, participants.c.club, tournaments.c.sport)
        .select_from(participants.join(tournaments, participants.c.tournament_id == tournaments.c.id))
        .order_by(tournaments.c.created_at, tournaments.c.id, participants.c.id)
    ).fetchall()
    made = {}
    now = datetime.now(timezone.utc)
    for pid, name, club, sport in rows:
        key = (sport, " ".join((name or "").split()).casefold())
        if key not in made:
            made[key] = conn.execute(
                players.insert().values(sport=sport, name=name, club=club or "", created_at=now).returning(players.c.id)
            ).scalar_one()
        elif club:
            conn.execute(players.update().where(players.c.id == made[key]).values(club=club))
        conn.execute(participants.update().where(participants.c.id == pid).values(player_id=made[key]))


